package relayverify

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// The proof fixtures under testdata are generated by testdata/generate, offline, with throwaway
// keys. They are UNCONFIRMED until control-plane recomputes them independently.

func fixture(t *testing.T, name string) []byte {
	t.Helper()
	b, err := os.ReadFile(filepath.Join("testdata", filepath.FromSlash(name)))
	if err != nil {
		t.Fatalf("failed to read fixture %s: %v", name, err)
	}

	return b
}

// publicKey reads a throwaway public key by label from testdata/public-keys.txt.
func publicKey(t *testing.T, label string) [32]byte {
	t.Helper()
	for _, line := range strings.Split(string(fixture(t, "public-keys.txt")), "\n") {
		if l, h, ok := strings.Cut(line, " "); ok && l == label {
			return mustHex32(t, h)
		}
	}
	t.Fatalf("no public key labelled %s", label)

	return [32]byte{}
}

func fixturePins(t *testing.T) Pins {
	return Pins{
		CurrentRoot:   mustHex32(t, testRootPubHex),
		NextRoot:      publicKey(t, "next-root"),
		CurrentPolicy: fixture(t, "policy/current.sigsum-policy"),
		NextPolicy:    fixture(t, "policy/next.sigsum-policy"),
	}
}

func fixtureVerifier(t *testing.T) *Verifier {
	t.Helper()
	v, err := NewVerifier(fixturePins(t))
	if err != nil {
		t.Fatalf("NewVerifier(fixture pins) error = %v", err)
	}

	return v
}

// baseBundle is vectors C and L, each with a proof under the current policy.
func baseBundle(t *testing.T) Bundle {
	return Bundle{
		RelayList:               fixture(t, "list/vector-l.json"),
		RelayListProof:          fixture(t, "list/vector-l.proof"),
		SigningCertificate:      fixture(t, "certificate/vector-c.json"),
		SigningCertificateProof: fixture(t, "certificate/vector-c.current.proof"),
	}
}

func certBundle(t *testing.T, cert, certProof string) Bundle {
	b := baseBundle(t)
	b.SigningCertificate, b.SigningCertificateProof = fixture(t, cert), fixture(t, certProof)

	return b
}

func listBundle(t *testing.T, list, listProof string) Bundle {
	b := baseBundle(t)
	b.RelayList, b.RelayListProof = fixture(t, list), fixture(t, listProof)

	return b
}

// asOfWithinTheList is between vector L's generated_at and expires_at.
var asOfWithinTheList = time.Date(2026, 1, 2, 12, 0, 0, 0, time.UTC)

// requireRefused requires Verify to return exactly want, BARE: == rather than errors.Is, because
// a wrapped error is how input reaches an error string. Verified is not comparable (a Document
// holds slices), so "no result alongside a refusal" is checked through its accessors.
func requireRefused(t *testing.T, b Bundle, want error) {
	t.Helper()
	got, err := fixtureVerifier(t).Verify(b, 0, asOfWithinTheList)
	if err != want {
		t.Fatalf("Verify() error = %v, want %v (bare)", err, want)
	}
	if got.Document().Version() != 0 || got.Expired() {
		t.Error("Verify() returned a result alongside its refusal")
	}
}

func requireAccepted(t *testing.T, b Bundle) Verified {
	t.Helper()
	got, err := fixtureVerifier(t).Verify(b, 0, asOfWithinTheList)
	if err != nil {
		t.Fatalf("Verify() error = %v, want nil", err)
	}

	return got
}

func TestTheFixturesAreTheContractVectors(t *testing.T) {
	if string(fixture(t, "certificate/vector-c.json")) != vectorC {
		t.Error("certificate/vector-c.json is not the contract's vector C")
	}
	if string(fixture(t, "list/vector-l.json")) != vectorL {
		t.Error("list/vector-l.json is not the contract's vector L")
	}
	// Both fixture policies parse and require a witness.
	fixtureVerifier(t)
}
